// Motion clips for a rig, read from Lottie documents: one layer per bone, its rotation keyframes are the
// joint's angle targets. Clips are generated by scripts/build-rig-clips.mjs and play in any Lottie viewer.
import { point, type Point } from '../../engine/src/geometry';
import type { RigPose, Skeleton } from './rig-skeleton';

interface ClipTrack {
  /** One sample per frame, 0..frames inclusive. */
  turn?: Float32Array;
  stretch?: Float32Array;
  shiftX?: Float32Array;
  shiftY?: Float32Array;
}
export interface RigClip {
  readonly name: string;
  /** Length in frames. A looping clip's last frame repeats its first. */
  readonly frames: number;
  readonly loop: boolean;
  /** Named instants in frames, such as the `contact` of a blow. */
  readonly markers: Readonly<Record<string, number>>;
  /** Feet hold their ground and legs are solved to reach them, rather than swinging by their own angles. */
  readonly planted: boolean;
  readonly tracks: ReadonlyMap<string, ClipTrack>;
}

interface LottieValue {
  a?: number;
  k?: unknown;
  s?: boolean;
  x?: LottieValue;
  y?: LottieValue;
}
interface LottieKey {
  t: number;
  s?: number[];
  e?: number[];
  h?: number;
  i?: { x: number | number[]; y: number | number[] };
  o?: { x: number | number[]; y: number | number[] };
}
interface LottieLayer {
  nm?: string;
  ks?: { r?: LottieValue; p?: LottieValue; a?: LottieValue; s?: LottieValue };
}
interface LottieDocument {
  nm?: string;
  ip?: number;
  op?: number;
  layers?: LottieLayer[];
  markers?: { tm: number; cm: string }[];
}

const component = (value: number | number[] | undefined, index: number, fallback: number): number =>
  value === undefined ? fallback : typeof value === 'number' ? value : (value[index] ?? value[0] ?? fallback);
/** Progress along a Lottie easing curve whose handles are (x1, y1) and (x2, y2). */
function eased(x1: number, y1: number, x2: number, y2: number, time: number): number {
  if (x1 === y1 && x2 === y2) return time;
  const curve = (a: number, b: number, u: number) => {
    const v = 1 - u;
    return 3 * v * v * u * a + 3 * v * u * u * b + u * u * u;
  };
  let low = 0,
    high = 1,
    u = time;
  // Bisection is plenty: clips are baked once when they load.
  for (let step = 0; step < 24; step++) {
    const x = curve(x1, x2, u);
    if (Math.abs(x - time) < 1e-5) break;
    if (x < time) low = u;
    else high = u;
    u = (low + high) / 2;
  }
  return curve(y1, y2, u);
}
/** Bakes one dimension of a Lottie property into a sample per frame. */
function bake(
  value: LottieValue | undefined,
  dimension: number,
  start: number,
  frames: number,
): Float32Array | null {
  if (!value) return null;
  const out = new Float32Array(frames + 1);
  if (!value.a) {
    const k = value.k;
    const fixed =
      typeof k === 'number' ? k : Array.isArray(k) && typeof k[dimension] === 'number' ? k[dimension] : null;
    if (fixed === null) return null;
    return out.fill(fixed);
  }
  const keys = value.k as LottieKey[];
  if (!Array.isArray(keys) || !keys.length) return null;
  let at = 0;
  for (let frame = 0; frame <= frames; frame++) {
    const time = start + frame;
    while (at < keys.length - 2 && time >= keys[at + 1].t) ++at;
    const from = keys[at],
      to = keys[at + 1],
      a = from.s?.[dimension] ?? 0;
    if (!to || time <= from.t) {
      out[frame] = a;
      continue;
    }
    const b = from.e?.[dimension] ?? to.s?.[dimension] ?? a;
    if (time >= to.t || from.h) {
      // Past the last key the value stays; a held key keeps its own value until the next.
      out[frame] = time >= to.t ? b : a;
      continue;
    }
    const span = Math.max(1e-6, to.t - from.t),
      t = Math.min(1, (time - from.t) / span),
      progress = eased(
        component(from.o?.x, dimension, 0),
        component(from.o?.y, dimension, 0),
        component(from.i?.x, dimension, 1),
        component(from.i?.y, dimension, 1),
        t,
      );
    out[frame] = a + (b - a) * progress;
  }
  return out;
}
const varies = (samples: Float32Array | null, rest: number): samples is Float32Array =>
  !!samples && samples.some((value) => Math.abs(value - rest) > 1e-6);

/**
 * Reads a rig clip. Every layer is a bone or a controller named by `nm`; its anchor is the joint at
 * rest, so `rotation` is the joint's turn, `position - anchor` its shift and vertical `scale` its
 * stretch. Markers name instants; a `planted` marker says the feet hold their ground.
 */
export function readRigClip(json: unknown): RigClip {
  // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: every field read below is checked or defaulted.
  const document = json as LottieDocument,
    start = document.ip ?? 0,
    frames = Math.round((document.op ?? 0) - start);
  if (!(frames > 0) || !Array.isArray(document.layers)) throw new Error('A rig clip needs frames and layers');
  const markers: Record<string, number> = {},
    tracks = new Map<string, ClipTrack>();
  for (const marker of document.markers ?? []) markers[marker.cm] = marker.tm - start;
  const radians = Math.PI / 180;
  for (const layer of document.layers) {
    if (!layer.nm || !layer.ks) continue;
    const track: ClipTrack = {},
      turn = bake(layer.ks.r, 0, start, frames),
      position = layer.ks.p,
      split = position?.s === true,
      x = split ? bake(position?.x, 0, start, frames) : bake(position, 0, start, frames),
      y = split ? bake(position?.y, 0, start, frames) : bake(position, 1, start, frames),
      anchorX = bake(layer.ks.a, 0, start, 0)?.[0] ?? 0,
      anchorY = bake(layer.ks.a, 1, start, 0)?.[0] ?? 0,
      tall = bake(layer.ks.s, 1, start, frames);
    if (varies(turn, 0)) track.turn = turn.map((degrees) => degrees * radians);
    if (varies(x, anchorX)) track.shiftX = x.map((value) => value - anchorX);
    if (varies(y, anchorY)) track.shiftY = y.map((value) => value - anchorY);
    if (varies(tall, 100)) track.stretch = tall.map((percent) => percent / 100);
    if (track.turn || track.shiftX || track.shiftY || track.stretch) tracks.set(layer.nm, track);
  }
  return {
    name: document.nm ?? 'clip',
    frames,
    loop: !('once' in markers),
    markers,
    planted: 'planted' in markers,
    tracks,
  };
}

const sampleAt = (samples: Float32Array, frame: number): number => {
  const low = Math.floor(frame),
    high = Math.min(samples.length - 1, low + 1);
  return samples[low] + (samples[high] - samples[low]) * (frame - low);
};
/** A clip's frame for any time: loops wrap, one-shot clips hold their ends. */
export function clipFrame(clip: RigClip, frame: number): number {
  if (!clip.loop) return Math.max(0, Math.min(clip.frames, frame));
  const wrapped = frame % clip.frames;
  return wrapped < 0 ? wrapped + clip.frames : wrapped;
}

type Binding = readonly [bone: number, track: ClipTrack];
const bindings = new WeakMap<RigClip, WeakMap<Skeleton, Binding[]>>();
function bind(clip: RigClip, skeleton: Skeleton): Binding[] {
  let bySkeleton = bindings.get(clip);
  if (!bySkeleton) bindings.set(clip, (bySkeleton = new WeakMap()));
  let bound = bySkeleton.get(skeleton);
  if (!bound) {
    bound = [];
    // A figure simply ignores bones it does not have, and rests the ones a clip leaves alone.
    for (const [name, track] of clip.tracks) {
      const bone = skeleton.find(name);
      if (bone >= 0) bound.push([bone, track]);
    }
    bySkeleton.set(skeleton, bound);
  }
  return bound;
}
/** Poses `pose` from the clip at `frame`. `unit` scales shifts from the clip's mannequin to this figure. */
export function sampleClip(clip: RigClip, frame: number, skeleton: Skeleton, pose: RigPose, unit = 1): void {
  const at = clipFrame(clip, frame);
  pose.rest();
  for (const [bone, track] of bind(clip, skeleton)) {
    if (track.turn) pose.angle[bone] = sampleAt(track.turn, at);
    if (track.stretch) pose.stretch[bone] = sampleAt(track.stretch, at);
    if (track.shiftX) pose.shiftX[bone] = sampleAt(track.shiftX, at) * unit;
    if (track.shiftY) pose.shiftY[bone] = sampleAt(track.shiftY, at) * unit;
  }
}
/** A controller layer's shift at `frame`, such as `step.r`; zero when the clip has none. */
export function clipShift(clip: RigClip, name: string, frame: number): Point {
  const track = clip.tracks.get(name),
    at = clipFrame(clip, frame);
  return point(
    track?.shiftX ? sampleAt(track.shiftX, at) : 0,
    track?.shiftY ? sampleAt(track.shiftY, at) : 0,
  );
}
/** A bone's turn straight from the clip, for figures that are not a full skeleton. */
export function clipTurn(clip: RigClip, name: string, frame: number): number {
  const track = clip.tracks.get(name);
  return track?.turn ? sampleAt(track.turn, clipFrame(clip, frame)) : 0;
}
export function clipStretch(clip: RigClip, name: string, frame: number): number {
  const track = clip.tracks.get(name);
  return track?.stretch ? sampleAt(track.stretch, clipFrame(clip, frame)) : 1;
}
